content.text:
{
  "primary_meaning": "Jesus Christ as the sacrificial Lamb of God whose death atones for the sins of the world",
  "primary_basis": [
    "John 1:29",
    "John 1:36",
    "1 Corinthians 5:7",
    "Isaiah 53:7",
    "Exodus 12 (Passover lamb typology)",
    "Revelation 5:6–14"
  ],
  "alternatives": [
    {
      "meaning": "Symbol of meekness, innocence, and purity",
      "basis": [
        "Isaiah 53:7",
        "general pastoral and sacrificial imagery in the Old Testament"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The triumphant, conquering Lamb who judges and reigns",
      "basis": [
        "Revelation 5–22 (Lamb who opens the seals, receives worship, defeats enemies)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Believers or disciples as vulnerable lambs needing protection",
      "basis": [
        "Luke 10:3",
        "John 21:15"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "The Christological identification of the Lamb as the atoning sacrifice is the overwhelmingly dominant and stable reading across historic Christian interpretation, drawing on Passover typology, Isaiah’s Servant, and New Testament fulfillment language. Other nuances remain secondary aspects of the same figure rather than competing primary symbols."
}
